741  struct ChainSubtable
   742  {
   743    friend struct Chain;
   744
   745    inline unsigned int get_size (void) const { return length; }
   746    inline unsigned int get_type (void) const { return coverage & SubtableType; }
   747
   748    enum Coverage
   749    {
   750      Vertical            = 0x80000000,   /* If set, this subtable will only be applied
   751                                           * to vertical text. If clear, this subtable
   752                                           * will only be applied to horizontal text. */
   753      Descending          = 0x40000000,   /* If set, this subtable will process glyphs
   754                                           * in descending order. If clear, it will
   755                                           * process the glyphs in ascending order. */
   756      AllDirections       = 0x20000000,   /* If set, this subtable will be applied to
   757                                           * both horizontal and vertical text (i.e.
   758                                           * the state of bit 0x80000000 is ignored). */
   759      Logical             = 0x10000000,   /* If set, this subtable will process glyphs
   760                                           * in logical order (or reverse logical order,
   761                                           * depending on the value of bit 0x80000000). */
   762      Reserved            = 0x0FFFFF00,   /* Reserved, set to zero. */
   763      SubtableType        = 0x000000FF,   /* Subtable type; see following table. */
   764    };
   765    enum Type
   766    {
   767      Rearrangement       = 0,
   768      Contextual          = 1,
   769      Ligature            = 2,
   770      Noncontextual       = 4,
   771      Insertion           = 5
   772    };
   773
   774    template <typename context_t>
   775    inline typename context_t::return_t dispatch (context_t *c) const
   776    {
   777      unsigned int subtable_type = get_type ();
   778      TRACE_DISPATCH (this, subtable_type);
   779      switch (subtable_type) {
   780      case Rearrangement:         return_trace (c->dispatch (u.rearrangement));
   781      case Contextual:            return_trace (c->dispatch (u.contextual));
   782      case Ligature:              return_trace (c->dispatch (u.ligature));
   783      case Noncontextual:         return_trace (c->dispatch (u.noncontextual));
   784      case Insertion:             return_trace (c->dispatch (u.insertion));
   785      default:                    return_trace (c->default_return_value ());
   786      }
   787    }
   788
   789    inline bool sanitize (hb_sanitize_context_t *c) const
   790    {
   791      TRACE_SANITIZE (this);
   792      if (!length.sanitize (c) ||
   793          length < min_size ||
   794          !c->check_range (this, length))
   795        return_trace (false);
   796
   797      return_trace (dispatch (c));
   798    }
   799
   800    protected:
   801    HBUINT32      length;         /* Total subtable length, including this header. */
   802    HBUINT32      coverage;       /* Coverage flags and subtable type. */
   803    HBUINT32      subFeatureFlags;/* The 32-bit mask identifying which subtable this is. */
   804    union {
   805    RearrangementSubtable         rearrangement;
   806    ContextualSubtable            contextual;
   807    LigatureSubtable              ligature;
   808    NoncontextualSubtable         noncontextual;
   809    InsertionSubtable             insertion;
   810    } u;
